const hero=document.querySelector(".hero");const reducedMotion=matchMedia("(prefers-reduced-motion: reduce)");let pending=false;let visible=true;function update(){pending=false;if(!hero)return;const rect=hero.getBoundingClientRect();const mobile=innerWidth<=760;const progress=reducedMotion.matches?0:Math.min(1,Math.max(0,-rect.top/(mobile?500:450)));hero.style.setProperty("--media-scale",reducedMotion.matches?"1":String(.965+progress*.045));hero.style.setProperty("--media-y",`${progress*(mobile?5:10)}px`);hero.style.setProperty("--media-radius",`${8-progress*5}px`)}function schedule(){if(!pending&&visible){pending=true;requestAnimationFrame(update)}}if(hero){if("IntersectionObserver"in window){new IntersectionObserver(([entry])=>{visible=entry.isIntersecting;if(visible)schedule()}).observe(hero)}window.addEventListener("scroll",schedule,{passive:true});window.addEventListener("resize",schedule,{passive:true});reducedMotion.addEventListener("change",update);update()}for(const link of document.querySelectorAll("[data-hero-category]")){link.addEventListener("click",()=>{document.querySelector(`.category[data-category="${link.dataset.heroCategory}"]`)?.click()})}if("IntersectionObserver"in window){let observeContent2=function(){for(const element of document.querySelectorAll(".hero-copy, .hero-food-card, .section-heading, .product, .location > div")){if(observed.has(element))continue;observed.add(element);reveal.observe(element)}};var observeContent=observeContent2;const reveal=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;const element=entry.target;const productIndex=element.classList.contains("product")?[...element.parentElement.children].indexOf(element)%3:0;element.style.setProperty("--entry-delay",`${productIndex*45}ms`);element.classList.add("motion-enter");element.addEventListener("animationend",()=>element.classList.remove("motion-enter"),{once:true});reveal.unobserve(element)}},{threshold:.08,rootMargin:"0px 0px -18px 0px"});const observed=new WeakSet;observeContent2();const products=document.querySelector("#products");if(products)new MutationObserver(observeContent2).observe(products,{childList:true})}
